#!/bin/sh
# GENERATED from lib/git-hooks/resolve-tool.sh by scripts/sync-shared-copies.sh. Do not edit this copy:
# edit the canonical source, then rerun the script.
# shellcheck shell=bash
# Select and run a format or lint plugin's shipped adapter for a file: the
# shared part of every format and lint plugin's batch hook and git-hook
# entries. The contract is the check-placement convention's "Hooks run the
# shipped adapter" section. Hooks never run an ecosystem record's command
# (https://github.com/melodic-software/claude-code-plugins/blob/main/docs/contracts/check-placement/README.md#hooks-run-the-shipped-adapter);
# /toolchain:lint and /toolchain:check run it on request.
#
# SINGLE SOURCE OF TRUTH: lib/git-hooks/resolve-tool.sh at the marketplace repo
# root. Plugin copies are generated by scripts/sync-shared-copies.sh.
#
# Sourced by bash (3.2 or later). The plugin sets, before calling:
#   RT_PLUGIN   the plugin name
#   RT_IDS      the ecosystem ids whose records it reports, space-separated
# and defines its adapter:
#   rt_adapter <concern> <file> <root>     0 when the adapter governs <file>
#                                          (the tool's own config opts it in);
#                                          sets RT_ADAPTER, RT_SCRIPT, RT_DIR,
#                                          RT_TOOL, RT_BIN, RT_INSTALL and
#                                          optionally RT_CONFIGS and RT_DETAIL
#   rt_adapter_in_repo <concern> <root>    0 when the adapter's config is in the
#                                          repository; sets RT_ADAPTER, RT_TOOL,
#                                          RT_BIN and RT_DETAIL (also on 1, to
#                                          say why nothing resolved)
#
#   rt_resolve <file> <concern> <root>   concern is format or lint. Sets
#     RT_SOURCE  adapter:<name> | none
#     RT_SCRIPT  the adapter's command; files reach it as "$@", never spliced
#   rt_group <concern> <root> <files...>  resolve many files and group them by
#   rt_use <i>                           command; RT_GN groups, RT_FILES each
#   rt_run <files...>        run RT_SCRIPT as `sh -c "$RT_SCRIPT" sh <files...>`
#                            from RT_DIR, in chunks under the Windows
#                            command-line limit; a name starting with - gains
#                            ./; returns the highest exit status
#   rt_lint <files...>       rt_run, then rt_normalize its output
#   rt_normalize <file> <status>  print each "<path>:<line>[:<col>]: <message>"
#                            line as repo-relative "<path>:<line>: <message>";
#                            returns 3, showing the output on stderr, when
#                            <status> is non-zero and no finding parsed
#   rt_require               the entries' missing-tool rule, as a status
#   rt_found <bin>           0 when the adapter's binary is runnable
#   rt_print <concern> <root> [<file>...]
#                            one TSV row for the repository, or one per file:
#                            plugin, concern, source, tool, found (yes | no |
#                            n/a), detail. Executes nothing.
#   rt_standards_file <root> <path>
#                            0, with RT_STANDARDS_FILE set to <path> in the
#                            standards repository, when <root>'s
#                            docs/conventions/source-control.yaml names one in
#                            standards_repository (<owner>/<repo>) and a local
#                            checkout holds the file: STANDARDS_DIR when set,
#                            else <ghq root>/github.com/<owner>/<repo> (git
#                            config ghq.root, default ~/ghq). 1, with it empty,
#                            otherwise: the adapter keeps its own default.

# shellcheck disable=SC2034 # the RT_* results are read by the plugin that sources this file
RT_PLUGIN="${RT_PLUGIN:-}"
RT_IDS="${RT_IDS:-}"
RT_ROOT=""
RT__ARGMAX=24000

rt__reset() {
  RT_SOURCE=none RT_SCRIPT="" RT_DIR="" RT_TOOL="" RT_BIN="" RT_INSTALL=""
  RT_ADAPTER="" RT_CONFIGS="" RT_DETAIL=""
}
rt__reset

rt_git() {
  if declare -F hook::git_untrusted >/dev/null; then hook::git_untrusted "$@"; else git "$@"; fi
}

rt_resolve() { # <file> <concern> <root>
  rt__reset
  RT_ROOT="$3"
  if declare -F rt_adapter >/dev/null && rt_adapter "$2" "$1" "$3"; then
    RT_SOURCE="adapter:$RT_ADAPTER"
  fi
  return 0
}

# rt_group <concern> <root> <files...>: rt_resolve each file and group the
# files that resolve to one command. Sets RT_GN, the group count, and per group
# i the RT_G_* arrays rt_use reads. Files no adapter governs are in no group.
rt_group() {
  local concern="$1" root="$2" f key i found
  shift 2
  RT_GN=0
  RT_G_KEY=() RT_G_SCRIPT=() RT_G_DIR=() RT_G_TOOL=() RT_G_BIN=()
  RT_G_INSTALL=() RT_G_CONFIGS=() RT_G_SOURCE=() RT_G_FILES=()
  for f in "$@"; do
    rt_resolve "$f" "$concern" "$root"
    [[ "$RT_SOURCE" == adapter:* ]] || continue
    key="$RT_SOURCE|$RT_DIR|$RT_BIN|$RT_SCRIPT"
    found=""
    for i in "${!RT_G_KEY[@]}"; do
      [[ "${RT_G_KEY[i]}" == "$key" ]] && found="$i" && break
    done
    if [[ -z "$found" ]]; then
      found=$RT_GN
      RT_GN=$((RT_GN + 1))
      RT_G_KEY[found]="$key" RT_G_SOURCE[found]="$RT_SOURCE" RT_G_SCRIPT[found]="$RT_SCRIPT"
      RT_G_DIR[found]="$RT_DIR" RT_G_TOOL[found]="$RT_TOOL" RT_G_BIN[found]="$RT_BIN"
      RT_G_INSTALL[found]="$RT_INSTALL" RT_G_CONFIGS[found]="$RT_CONFIGS"
      RT_G_FILES[found]=""
    fi
    RT_G_FILES[found]+="$f"$'\x1f'
  done
}

# rt_use <i>: set RT_* to group i, and RT_FILES to its files.
rt_use() {
  local f rest
  RT_SOURCE="${RT_G_SOURCE[$1]}" RT_SCRIPT="${RT_G_SCRIPT[$1]}" RT_DIR="${RT_G_DIR[$1]}"
  RT_TOOL="${RT_G_TOOL[$1]}" RT_BIN="${RT_G_BIN[$1]}" RT_INSTALL="${RT_G_INSTALL[$1]}"
  RT_CONFIGS="${RT_G_CONFIGS[$1]}"
  RT_FILES=()
  rest="${RT_G_FILES[$1]}"
  while [[ -n "$rest" ]]; do
    f="${rest%%$'\x1f'*}"
    rest="${rest#*$'\x1f'}"
    RT_FILES+=("$f")
  done
}

# rt__arg <file>: sets RT__A to <file> as RT_DIR sees it; a leading dash
# gains ./ so no tool reads a file name as an option.
rt__arg() {
  local abs="$1"
  [[ "$abs" == /* || "$abs" == [A-Za-z]:[\\/]* ]] || abs="$PWD/$abs"
  [[ "$abs" == "$RT_DIR/"* ]] && abs="${abs#"$RT_DIR/"}"
  [[ "$abs" == -* ]] && abs="./$abs"
  RT__A="$abs"
}

rt_run() { # <files...>
  local f a size=0 status=0 rc chunk=()
  local args=()
  for f in "$@"; do
    rt__arg "$f"
    args+=("$RT__A")
  done
  for a in "${args[@]}" ""; do
    if [[ -z "$a" ]] || ((size + ${#a} + 1 > RT__ARGMAX && ${#chunk[@]})); then
      if ((${#chunk[@]})); then
        (cd "$RT_DIR" && RT_BIN="$RT_BIN" sh -c "$RT_SCRIPT" sh "${chunk[@]}")
        rc=$?
        ((rc > status)) && status=$rc
      fi
      chunk=() size=0
    fi
    [[ -n "$a" ]] && chunk+=("$a") && size=$((size + ${#a} + 1))
  done
  return "$status"
}

# rt__finding <line>: sets RT__F to the line as a repo-relative finding, or
# to empty when the line is not one.
rt__finding() {
  local line="${1%$'\r'}" drive="" path rel
  RT__F=""
  if [[ "$line" =~ ^[A-Za-z]:[\\/] ]]; then
    drive="${line:0:2}" line="${line:2}"
  fi
  [[ "$line" =~ ^([^:]+):([0-9]+)(:[0-9]+)?:[[:space:]]?(.*)$ ]] || return 0
  path="$drive${BASH_REMATCH[1]}"
  path="${path//\\//}"
  path="${path#./}"
  if [[ "$path" == /* || "$path" == [A-Za-z]:/* ]]; then
    rel="${path#"$RT_ROOT/"}"
  elif [[ "$RT_DIR" == "$RT_ROOT" || -z "$RT_DIR" ]]; then
    rel="$path"
  else
    rel="${RT_DIR#"$RT_ROOT/"}/$path"
  fi
  RT__F="$rel:${BASH_REMATCH[2]}: ${BASH_REMATCH[4]}"
}

rt_normalize() { # <output file> <status>
  local line found=0
  while IFS= read -r line || [[ -n "$line" ]]; do
    rt__finding "$line"
    [[ -n "$RT__F" ]] && found=1 && printf '%s\n' "$RT__F"
  done <"$1"
  if (($2 != 0 && !found)); then
    printf '%s: %s exited %s and reported no <path>:<line> finding, so the change was not checked:\n' \
      "${RT_PLUGIN:-lint}" "${RT_TOOL:-the linter}" "$2" >&2
    cat "$1" >&2
    return 3
  fi
  return 0
}

rt_lint() { # <files...>
  local out status tmp="${CHECKS_TMP:-}" own=""
  if [[ -z "$tmp" ]]; then
    tmp="$(mktemp -d "${TMPDIR:-/tmp}/rt.XXXXXX")" || return 3
    own=1
  fi
  out="$tmp/rt-lint.$$"
  rt_run "$@" >"$out" 2>&1
  rt_normalize "$out" "$?"
  status=$?
  rm -f "$out"
  [[ -n "$own" ]] && rm -rf "$tmp"
  return "$status"
}

rt_standards_file() {
  local repo base pat='^[A-Za-z0-9_-][A-Za-z0-9_.-]*/[A-Za-z0-9_-][A-Za-z0-9_.-]*$'
  RT_STANDARDS_FILE=""
  if [[ "${RT__STD_FOR:-}" != "$1" ]]; then
    RT__STD_FOR="$1" RT__STD_DIR=""
    repo="$(awk '/^standards_repository[[:space:]]*:/ {
        v = $0; sub(/^[^:]*:[[:space:]]*/, "", v); sub(/[[:space:]]+#.*$/, "", v)
        sub(/[[:space:]\r]+$/, "", v); gsub(/^["\047]|["\047]$/, "", v); print v; exit
      }' "$1/docs/conventions/source-control.yaml" 2>/dev/null)"
    if [[ "$repo" =~ $pat ]]; then
      if [[ -n "${STANDARDS_DIR:-}" ]]; then
        RT__STD_DIR="$STANDARDS_DIR"
      else
        base="$(git config --path --get ghq.root 2>/dev/null)"
        base="${base%$'\r'}"
        RT__STD_DIR="${base:-${HOME:-}/ghq}/github.com/$repo"
      fi
      RT__STD_DIR="$(CDPATH='' cd -- "$RT__STD_DIR" 2>/dev/null && pwd)"
    fi
  fi
  [[ -n "$RT__STD_DIR" && -f "$RT__STD_DIR/$2" ]] || return 1
  RT_STANDARDS_FILE="$RT__STD_DIR/$2"
}

rt_found() { # <bin>
  if [[ "$1" == */* ]]; then
    [[ -x "$1" ]]
  else
    command -v "$1" >/dev/null 2>&1
  fi
}

# rt_require: a git-hook entry's missing-tool rule (check-lib.sh's
# checks_require_tool) for the adapter's binary, keyed by RT_TOOL, as a status
# so a missing tool stops only its own group: 0 the tool is there; 1 skip this
# group (checks.skipmissing names it, or a person runs the hook); 2 fail the
# entry (an agent runs it). The line is printed either way.
rt_require() {
  rt_found "$RT_BIN" && return 0
  if checks_skip_listed "$RT_TOOL"; then
    printf 'SKIPPED: %s (missing)\n' "$RT_TOOL" >&2
    return 1
  fi
  if checks_is_agent; then
    printf 'FAIL: %s missing. Install: %s\n' "$RT_TOOL" "$RT_INSTALL" >&2
    printf 'To skip only while %s is missing: git -c checks.skipmissing=%s %s ...\n' "$RT_TOOL" "$RT_TOOL" "$(checks_git_verb)" >&2
    return 2
  fi
  printf 'NOTICE: %s missing, so this check did not run. Install: %s\n' "$RT_TOOL" "$RT_INSTALL" >&2
  return 1
}

# rt__record_note <root>: sets RT__NOTE to a sentence naming each record the
# plugin's ids have, which hooks never run.
rt__record_note() {
  local id
  RT__NOTE=""
  for id in $RT_IDS; do
    [[ -f "$1/docs/conventions/ecosystems/$id.yaml" || -f "$1/docs/conventions/ecosystems/$id.local.yaml" ||
      -f "$1/.claude/ecosystems/$id.yaml" || -f "$1/.claude/ecosystems/$id.local.yaml" || -f "${HOME:-}/.claude/ecosystems/$id.yaml" ]] || continue
    RT__NOTE+="${RT__NOTE:+; }the $id record is not run by hooks; /toolchain:lint and /toolchain:check run it"
  done
}

rt_print() { # <concern> <root> [<file>...]
  local concern="$1" root="$2" f found tool detail
  rt__record_note "$root"
  if (($# > 2)); then
    shift 2
    for f in "$@"; do
      rt_resolve "$f" "$concern" "$root"
      found=n/a tool=""
      if [[ "$RT_SOURCE" == adapter:* ]]; then
        tool="$RT_TOOL" found=no
        rt_found "$RT_BIN" && found=yes
      fi
      detail="$RT_DETAIL"
      [[ -n "$RT__NOTE" ]] && detail="${detail:+$detail; }$RT__NOTE"
      printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$RT_PLUGIN" "$concern" "$RT_SOURCE" "$tool" "$found" "$detail"
    done
    return 0
  fi
  rt__reset
  RT_ROOT="$root"
  local source=none
  if declare -F rt_adapter_in_repo >/dev/null && rt_adapter_in_repo "$concern" "$root"; then
    source="adapter:$RT_ADAPTER" tool="$RT_TOOL" found=no
    rt_found "$RT_BIN" && found=yes
  else
    tool="" found=n/a
  fi
  detail="$RT_DETAIL"
  [[ -n "$RT__NOTE" ]] && detail="${detail:+$detail; }$RT__NOTE"
  printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$RT_PLUGIN" "$concern" "$source" "$tool" "$found" "$detail"
}
